Under the availability of the stochastic zeroth-order oracle, with
		\begin{align}
		\nu_{X[Y]}=\eta_t^2\left(d_{X[Y]}+3\right)^{-\frac{3}{2}}\quad \eta_t=\frac{4T^{-\alpha}}{\mu} \quad m_t^{X[Y]}=\frac{\left(d_{X[Y]}+5\right)}{\eta_t^2} \quad \alpha=\frac{1}{4}, \label{eq:statepsdeletamtchoicezero1}
		\end{align}
		we obtain
		\begin{align}\label{eq:rsspboundzero1}
		\mathfrak{R}_{SSP}\leq \mathcal{O}\left(\left(\sigma+1\right)T^\frac{3}{4}\right). 
		\end{align}
		Hence, the total number of calls to the stochastic zeroth-order oracle is $\mathcal{O}\left(\left(d_X+d_Y\right)T^\frac{5}{2}\right)$.

Furthermore, by choosing
			\begin{align}
		\nu_{X[Y]}=\eta_t^4\left(d{X[Y]}+3\right)^{-\frac{3}{2}}\quad \eta_t=\frac{4T^{-\alpha}}{\mu} \quad m_t^{X[Y]}=\frac{\left(d_{X[Y]}+5\right)}{\eta_t^4}\quad \alpha=\frac{1}{4}, \label{eq:statepsdeletamtchoicezero2}
		\end{align}
		we obtain,
		\begin{align}
		\mathfrak{R}_{SSP}\leq \mathcal{O}\left(\sigma T^\frac{1}{2}+T^\frac{3}{4}\right). \label{eq:rsspboundzero2} 
		\end{align}
		Hence, the total number of calls to the stochastic zeroth-order  oracle is $\mathcal{O}\left(\left(d_X+d_Y\right)T^3\right)$.

Under the availability of the stochastic first-order oracle, with
		\begin{align}
	    \eta_t=\frac{4T^{-\alpha}}{\mu} \quad m_t=\frac{1}{\eta_t^2}\quad \alpha=\frac{1}{4}, \label{eq:statepsdeletamtchoicefirst1}
		\end{align}
		we obtain,
		\begin{align}
		\mathfrak{R}_{SSP}\leq \mathcal{O}\left(\left(\sigma+1\right)T^\frac{3}{4}\right). \label{eq:rsspboundfirst1}
		\end{align}

Furthermore, by choosing,
		\begin{align}
		\eta_t=\frac{4T^{-\alpha}}{\mu} \quad m_t=\frac{1}{\eta_t^4}\quad \alpha=\frac{1}{4}, \label{eq:statepsdeletamtchoicefirst2}
		\end{align}
		we obtain,
		\begin{align}
		\mathfrak{R}_{SSP}\leq \mathcal{O}\left(\sigma T^\frac{1}{2}+T^\frac{3}{4}\right). \label{eq:rsspboundfirst2} 
		\end{align}

Under the availability of the stochastic zeroth-order oracle, choosing
	\begin{align} \label{eq:inductionzero}
    \gamma_t = \frac{1}{\sqrt{t}} \quad m_t^{X[Y]}=2\left(d_{X[Y]}+5\right)t \quad \nu_{X[Y]}=\frac{\sqrt{2}}{\left(d_{X[Y]}+3\right)^\frac{3}{2}\sqrt{t}}
\end{align}
	we obtain 
	\begin{align}\label{eq:rsspboundfwzero}
		\mathfrak{R}_{SSP} \leq \order((1+\sigma)T^{\frac{3}{4}}).
	\end{align}
Hence, the total number of calls to the stochastic zeroth-order oracle is $\order((d_X+d_Y)T^2)$.

Then, for $V_T\leq T^\frac{\alpha}{\beta}$, running Algorithm~\ref{alg:EG}, we have:
	\begin{enumerate}[label=(\alph*)]
		\item Under the availability of the stochastic zeroth-order oracle, with
		\begin{align}
		\eta_t=\eta=\frac{4T^{-\alpha}V_T^\beta}{\mu} \quad  \nu_{X[Y]}=\eta^2\left(d_{X[Y]}+3\right)^{-\frac{3}{2}} \quad m_t^{X[Y]}=\frac{\left(d_{X[Y]}+5\right)}{\eta^{2}}, \label{eq:epsdeletamtchoicezero1}
		\end{align}
		we obtain,
		\begin{align}
		\mathfrak{R}_{DSPP}\leq \mathcal{O}\left(\sigma^2T^{1-{2\alpha}}V_T^{2\beta}+V_T^{1-2\beta}T^{2\alpha}\right).\label{eq:rdsppboundzero1}
		\end{align}

Under the availability of the stochastic zeroth-order oracle, with
	\begin{align}
	\gamma_t=\gamma=\sqrt{\frac{\max\left(2W_T,V_T\right)}{T}} \quad m_t^{X[Y]}=T\left(d_{X[Y]}+5\right) \quad \nu_{X[Y]}=\frac{1}{\sqrt{T\left(d_{X[Y]}+3\right)^3}},\label{eq:gammamtnuchoicedspmzero}
	\end{align}
	we obtain, 
	\begin{align}
	\mathfrak{R}_{DSPM}\leq \mathcal{O}\left(\sqrt{T\max\left(2W_T,V_T\right)}\left(1+\frac{\sigma^2}{\max\left(2W_T,V_T\right)}\right)\right). \label{eq:rdspmboundzero}
	\end{align}
	Hence, the total number of calls to the stochastic zeroth-order oracle is $\mathcal{O}\left(\left(d_X+d_Y\right)T^2\right)$.

Under the availability of the stochastic first-order oracle, with
	\begin{align}
	\gamma_t=\gamma=\sqrt{\frac{\max\left(2W_T,V_T\right)}{T}} \quad m_t=T, \label{eq:gammamtnuchoicedspmfirst}
	\end{align}
    we obtain
    \begin{align}
	\mathfrak{R}_{DSPM}\leq \mathcal{O}\left(\sqrt{T\max\left(2W_T,V_T\right)}\left(1+\frac{\sigma^2}{\max\left(2W_T,V_T\right)}\right)\right). \label{eq:rdspmboundfirst}
	\end{align}

Under the availability of the stochastic zeroth-order oracle, choosing
	\begin{align}
	\eta_t=\eta=V_T^\frac{1}{4} \quad \nu_{X[Y]}=\frac{1}{\left(d_{X[Y]}+6\right)^\frac{3}{2}\sqrt{T}} \quad m_t^{X[Y]}=\left(d_{X[Y]}+6\right)T, \label{eq:dspetanuzero}
	\end{align}
	we obtain,
	\begin{align}
	\mathfrak{R}_{DSP}\leq\mathcal{O}\left(\left(1+\sigma^2\right)V_T^\frac{1}{4}+\sigma \sqrt{T}\right). \label{eq:dspzero}
	\end{align}
	Hence, the total number of calls to the stochastic zeroth-order oracle is $\mathcal{O}\left(\left(d_X+d_Y\right)T^2\right)$.
